python
def bitRibbonsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a:
        count=0
        while x:
            x&=x-1
            count+=1
        out.append(count)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int bitRibbonsFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){int count=0;while(x!=0){x&=x-1;count++;}out.add(count);}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
